select * from (
select
REGIST_SEQNO registSeqno,
ITEM_ID itemId,
ITEM_NAME itemName,
STATUS status,
STATUS_DATE statusDate,
SUBMIT_TIME submitTime,
CHB_SUBMIT_DEADLINE chbSubmitDeadline,
SUBMIT_DEADLINE submitDeadline,
SUBMIT_FEEDBACK_STATUS submitFeedbackStatus,
SUBMIT_FEEDBACK_MSG submitFeedbackMsg,
SEND_STATUS sendStatus,
CREATE_USER createUser,
CREATE_TIME createTime,
UPDATE_USER updateUser,
UPDATE_TIME updateTime,
ORG_CODE orgCode,
DEPT_CODE deptCode
from LIQUIDITY_RISK_SUB


    DATE_FORMAT(CHB_SUBMIT_DEADLINE, '%Y-%m-%d') >= #{submitDeadLineStart,jdbcType=VARCHAR}


    and DATE_FORMAT(CHB_SUBMIT_DEADLINE, '%Y-%m-%d') <= #{submitDeadLineEnd,jdbcType=VARCHAR}



      #{item,jdbcType=VARCHAR}




      #{item,jdbcType=VARCHAR}




      #{item,jdbcType=VARCHAR}



    and DATE_FORMAT(STATUS_DATE, '%Y-%m-%d') >= #{statusDateStart,jdbcType=VARCHAR}


    and DATE_FORMAT(STATUS_DATE, '%Y-%m-%d') <= #{statusDateEnd,jdbcType=VARCHAR}


    and DATE_FORMAT(SUBMIT_TIME, '%Y-%m-%d') >= #{submitTimeStart,jdbcType=VARCHAR}


    and DATE_FORMAT(SUBMIT_TIME, '%Y-%m-%d') <= #{submitTimeEnd,jdbcType=VARCHAR}


    and termid >= #{termidDateStart,jdbcType=VARCHAR}


    and termid <= #{termidDateEnd,jdbcType=VARCHAR}



      #{submitFeedbackStatus,jdbcType=VARCHAR}



    and ITEM_ID  =  #{itemId,jdbcType=VARCHAR}


) ORDER BY STATUSDATE
